import * as cheerio from 'cheerio';

// Best-effort page metadata extraction (FR-002). Never throws; returns nulls
// for anything it cannot determine so saving can fall back (FR-004).
export async function fetchMetadata(url) {
  const result = { url, title: null, description: null, iconUrl: null, previewImageUrl: null };
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8000);
    const res = await fetch(url, {
      signal: controller.signal,
      redirect: 'follow',
      headers: { 'User-Agent': 'BookmarkManager/1.0 (+metadata)' },
    });
    clearTimeout(timer);
    const contentType = res.headers.get('content-type') || '';
    if (!contentType.includes('html')) {
      return result; // e.g. a PDF — nothing to parse
    }
    const html = await res.text();
    const $ = cheerio.load(html);
    const meta = (sel, attr = 'content') => {
      const el = $(sel).first();
      const v = el && el.attr(attr);
      return v && v.trim() ? v.trim() : null;
    };

    result.title =
      meta('meta[property="og:title"]') ||
      meta('meta[name="twitter:title"]') ||
      ($('title').first().text().trim() || null);
    result.description =
      meta('meta[property="og:description"]') ||
      meta('meta[name="twitter:description"]') ||
      meta('meta[name="description"]');
    result.previewImageUrl =
      meta('meta[property="og:image"]') || meta('meta[name="twitter:image"]');

    const iconHref =
      meta('link[rel="icon"]', 'href') ||
      meta('link[rel="shortcut icon"]', 'href') ||
      meta('link[rel="apple-touch-icon"]', 'href');
    try {
      result.iconUrl = iconHref
        ? new URL(iconHref, res.url || url).href
        : new URL('/favicon.ico', url).href;
      if (result.previewImageUrl) {
        result.previewImageUrl = new URL(result.previewImageUrl, res.url || url).href;
      }
    } catch {
      // ignore URL resolution failures
    }
  } catch {
    // Unreachable/blocked page: return the empty (null) result (FR-004).
  }
  return result;
}

