.empty-state { color: var(--muted); padding: 2rem 0; text-align: center; }

.bulk-bar {
  display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap;
  background: #fffbe6; border: 1px solid #f5e08a; border-radius: 8px;
  padding: 0.5rem 0.75rem; margin-bottom: 0.75rem;
}
.bulk-count { font-weight: 600; }
.bulk-sep { flex: 1; }
.bulk-tagadd { display: flex; gap: 0.25rem; }
.bulk-tagadd input { width: 90px; }

.save-form, .prefs-panel, .import-export, .capture-controls {
  background: var(--panel); border: 1px solid var(--border); border-radius: 8px; padding: 1rem; margin-bottom: 1rem;
}
.save-form label, .prefs-panel label { display: block; margin: 0.6rem 0; }
.save-form label > input, .save-form label > textarea { margin-top: 0.25rem; }
.preview { max-width: 100%; max-height: 160px; border-radius: 6px; margin: 0.5rem 0; }
.modal { position: sticky; top: 0; z-index: 5; }

.prefs-head, .saved-views-head { display: flex; justify-content: space-between; align-items: center; }
.prefs-panel label select { margin-top: 0.25rem; }

.tag-input { position: relative; }
.tag-chips { display: flex; gap: 0.3rem; flex-wrap: wrap; margin-bottom: 0.3rem; }
.suggestions {
  position: absolute; z-index: 10; list-style: none; margin: 0.2rem 0 0; padding: 0.25rem;
  background: var(--panel); border: 1px solid var(--border); border-radius: 6px; width: 100%;
}
.suggestions button { width: 100%; text-align: left; border: none; background: none; }
.suggestions button:hover { background: var(--chip); }

.note-editor { border: 1px solid var(--border); border-radius: 6px; margin-top: 0.25rem; }
.note-toolbar { display: flex; gap: 0.25rem; padding: 0.3rem; border-bottom: 1px solid var(--border); }
.note-toolbar button { padding: 0.15rem 0.5rem; }
.note-area { min-height: 80px; padding: 0.5rem; outline: none; }
.note-area:empty::before { content: attr(data-placeholder); color: var(--muted); }

.saved-views { background: var(--panel); border: 1px solid var(--border); border-radius: 8px; padding: 0.75rem; }
.view-list { list-style: none; margin: 0.5rem 0 0; padding: 0; display: flex; flex-direction: column; gap: 0.2rem; }
.view-list li { display: flex; gap: 0.25rem; align-items: center; }
.view-open { flex: 1; text-align: left; }
.view-list li.active .view-open { background: var(--chip); }
.view-form { display: flex; flex-direction: column; gap: 0.4rem; margin-top: 0.5rem; }

.active-view-banner {
  display: flex; gap: 0.5rem; align-items: center;
  background: var(--chip); border-radius: 6px; padding: 0.5rem 0.75rem; margin-bottom: 0.75rem;
}
.file-label { display: inline-block; border: 1px dashed var(--border); border-radius: 6px; padding: 0.6rem; cursor: pointer; }
.file-label input { display: none; }
.button-link { display: inline-block; padding: 0.4rem 0.7rem; border: 1px solid var(--border); border-radius: 6px; text-decoration: none; }
.summary { color: #15803d; font-weight: 600; }
.capture-controls .row { margin: 0.35rem 0; }

@media (max-width: 720px) {
  .app-body { flex-direction: column; }
  .sidebar { width: 100%; }
  .card { flex-wrap: wrap; }
  .card-actions { flex-direction: row; }
}

